 "title": "Derive and validate task transform",
 "command": "cat > programs/task-e3280c98.py <<'PY'
def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); bg=max({v for row in g for v in row},key=lambda v:sum(row.count(v) for row in g))
    seen=set()
    for r in range(h):
      for c in range(w):
        v=g[r][c]
        if v==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          a,b=stack.pop(); cells.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if 0<=x<h and 0<=y<w and g[x][y]==v and (x,y) not in seen: seen.add((x,y)); stack.append((x,y))
        r0=min(a for a,b in cells); r1=max(a for a,b in cells); c0=min(b for a,b in cells); c1=max(b for a,b in cells)
        if (r1-r0+1)*(c1-c0+1)>len(cells) and len(cells)==2*((r1-r0)+(c1-c0)) and r1>r0+1 and c1>c0+1:
          if all(g[r0][j]==v and g[r1][j]==v for j in range(c0,c1+1)) and all(g[i][c0]==v and g[i][c1]==v for i in range(r0,r1+1)):
            for i in range(r0+1,r1):
              for j in range(c0+1,c1):
                if g[i][j]==bg: g[i][j]=2
    return g
PY
